1400	/// The [`crate::pipeline::StepStatus`] a status label and reason label name: the inverse of `StepStatus::label` and
1401	/// `StepStatus::reason`.
1402	fn parse_step_status(status: &str, reason: Option<&str>) -> napi::Result<crate::pipeline::StepStatus> {
1403	    use crate::pipeline::{NotRunReason, SkipReason, StepStatus, UnknownCause};
1404	
1405	    let fail = |msg: String| Err(napi::Error::from_reason(msg));
1406	    let with_reason = |expected: &str| -> napi::Result<&str> {
1407	        reason.ok_or_else(|| napi::Error::from_reason(format!("step status {status:?} needs a reason: {expected}")))
1408	    };
1409	    let unknown_reason = |r: &str, expected: &str| {
1410	        napi::Error::from_reason(format!("unknown reason {r:?} for step status {status:?}: expected {expected}"))
1411	    };
1412	    let plain = |s: StepStatus| match reason {
1413	        Some(r) => fail(format!("step status {status:?} takes no reason, got {r:?}")),
1414	        None => Ok(s),
1415	    };
1416	    match status {
1417	        "pending" => plain(StepStatus::Pending),
1418	        "running" => plain(StepStatus::Running),
1419	        "completed" => plain(StepStatus::Completed),
1420	        "completed_earlier" => plain(StepStatus::CompletedEarlier),
1421	        "failed" => plain(StepStatus::Failed),
1422	        "panicked" => plain(StepStatus::Panicked),
1423	        "outcome_unknown" => {
1424	            const EXPECTED: &str = "timeout, gateway, cancelled, interrupted or step_failed";
1425	            let cause = match with_reason(EXPECTED)? {
1426	                "timeout" => UnknownCause::Timeout,
1427	                "gateway" => UnknownCause::Gateway,
1428	                "cancelled" => UnknownCause::Cancelled,
1429	                "interrupted" => UnknownCause::Interrupted,
1430	                "step_failed" => UnknownCause::StepFailed,
1431	                other => return Err(unknown_reason(other, EXPECTED)),
1432	            };
1433	            Ok(StepStatus::OutcomeUnknown(cause))
1434	        }
1435	        "skipped" => {
1436	            const EXPECTED: &str = "prerequisite_failed or cancelled";
1437	            let why = match with_reason(EXPECTED)? {
1438	                "prerequisite_failed" => SkipReason::PrerequisiteFailed,
1439	                "cancelled" => SkipReason::Cancelled,
1440	                other => return Err(unknown_reason(other, EXPECTED)),
1441	            };
1442	            Ok(StepStatus::Skipped(why))
1443	        }
1444	        "not_run" => {
1445	            const EXPECTED: &str = "circuit_open, unverified or start_not_recorded";
1446	            let why = match with_reason(EXPECTED)? {
1447	                "circuit_open" => NotRunReason::CircuitOpen,
1448	                "unverified" => NotRunReason::Unverified,
1449	                "start_not_recorded" => NotRunReason::StartNotRecorded,
1450	                other => return Err(unknown_reason(other, EXPECTED)),
1451	            };
1452	            Ok(StepStatus::NotRun(why))
1453	        }
1454	        other => fail(format!("unknown step status {other:?}: expected one of {STEP_STATUSES}")),
1455	    }
1456	}
