2128	    #[test]
2129	    fn agent_response_hint_bytes_are_capped_across_calls() {
2130	        let mut r = JsAgentResponse::new("t".to_string());
2131	        let mut accepted = 0;
2132	        let err = loop {
2133	            match r.hint(big(MAX_STRING_BYTES)) {
2134	                Ok(()) => accepted += 1,
2135	                Err(e) => break e,
2136	            }
2137	            assert!(accepted <= 64, "65 one-MiB hints were accepted; the budget is per call only");
2138	        };
2139	        // "t" takes one byte, so 63 full hints fit and the 64th would pass 64 MiB.
2140	        assert_eq!(accepted, 63);
2141	        assert!(err.reason.starts_with("cumulative byte total "), "{}", err.reason);
2142	        assert!(err.reason.ends_with(&format!("exceeds maximum of {}", input::MAX_INPUT_BYTES)), "{}", err.reason);
2143	        let rendered = r.render_text().expect("still usable after the rejected hint");
2144	        assert!(rendered.len() < input::MAX_INPUT_BYTES + 4096, "rendered {} bytes", rendered.len());
2145	        r.hint("small".to_string()).expect("a hint that still fits is accepted");
2146	    }
