2203	    #[test]
2204	    fn agent_response_empty_sections_are_charged_for_their_name_and_overhead() {
2205	        // Each empty `items` / `kvItems` call still stores a section with a copy of the type name, so it costs bytes.
2206	        for kv in [false, true] {
2207	            let mut r = JsAgentResponse::new("t".repeat(MAX_NAME_BYTES));
2208	            let mut accepted = 0usize;
2209	            while accepted <= 1_000_000 {
2210	                let added = if kv { r.kv_items(vec![], None) } else { r.items(vec![], vec![], None) };
2211	                if added.is_err() {
2212	                    break;
2213	                }
2214	                accepted += 1;
2215	            }
2216	            // 64 MiB / (4 KiB name + overhead) is about 16k sections; uncharged, the loop would run past a million.
2217	            assert!(accepted < 20_000, "{accepted} empty sections accepted (kv: {kv})");
2218	            assert!(accepted > 10_000, "{accepted} empty sections accepted (kv: {kv}): overhead too large");
2219	        }
2220	    }
