2222	    #[test]
2223	    fn agent_response_rows_and_non_string_cells_are_charged_for_the_storage_they_keep() {
2224	        // `Array(100000).fill([])`: no strings at all, yet every call keeps 100,000 row vectors. Charging string
2225	        // bytes only let a loop of these retain gigabytes, since each call now appends a section instead of
2226	        // replacing the rows.
2227	        let empty_rows = || vec![Vec::<JsToonValue>::new(); MAX_ROWS];
2228	        let mut r = JsAgentResponse::new("t".to_string());
2229	        let mut accepted = 0usize;
2230	        while accepted < 1_000 {
2231	            if r.items(empty_rows(), vec![], None).is_err() {
2232	                break;
2233	            }
2234	            accepted += 1;
2235	        }
2236	        // 64 MiB / (100,000 rows * 24 bytes) is about 27 calls. Uncharged, the loop would run to its cap.
2237	        assert!(accepted < 100, "{accepted} calls of {MAX_ROWS} empty rows accepted");
2238	        assert!(accepted > 5, "{accepted} calls accepted: row charge is too large");
2239	
2240	        // A cell that is not a string also keeps a `Value`, so a number-only table is not free either.
2241	        let null_cell = || JsToonValue { r#type: "null".to_string(), ..JsToonValue::default() };
2242	        let mut r = JsAgentResponse::new("t".to_string());
2243	        assert!(r.items(vec![vec![null_cell()]], vec!["a".to_string()], None).is_ok(), "a null cell is a valid cell");
2244	        let mut accepted = 0usize;
2245	        while accepted < 100_000 {
2246	            if r.items(vec![vec![null_cell(); MAX_FIELDS]; 1_000], vec![], None).is_err() {
2247	                break;
2248	            }
2249	            accepted += 1;
2250	        }
2251	        assert!(accepted < 100, "{accepted} calls of 1M non-string cells accepted");
2252	    }
