2818	    /// Returns `true` if `line` contains the token `unsafe` used as a block
2819	    /// or item qualifier — i.e. immediately (modulo whitespace) followed by
2820	    /// `{`, `fn`, `impl`, or `trait` — approximating the regex
2821	    /// `\bunsafe\s*(\{|fn|impl|trait)` from AC-033a without a regex
2822	    /// dependency. Deliberately does not match `unsafe_code` (the attribute
2823	    /// token used by `#![deny(unsafe_code)]` / `#![allow(unsafe_code)]`,
2824	    /// covered separately by AC-033b) because the character immediately
2825	    /// following `unsafe` there is `_`, which fails the word-boundary check.
2826	    fn line_has_unsafe_qualifier(line: &str) -> bool {
2827	        let bytes = line.as_bytes();
2828	        let mut i = 0;
2829	        while let Some(rel) = line[i..].find("unsafe") {
2830	            let start = i + rel;
2831	            let before_ok = start == 0 || !(bytes[start - 1].is_ascii_alphanumeric() || bytes[start - 1] == b'_');
2832	            let after = start + "unsafe".len();
2833	            let after_ok = after >= bytes.len() || !(bytes[after].is_ascii_alphanumeric() || bytes[after] == b'_');
2834	            if before_ok && after_ok {
2835	                let mut j = after;
2836	                while j < bytes.len() && bytes[j].is_ascii_whitespace() {
2837	                    j += 1;
2838	                }
2839	                let rest = &line[j..];
2840	                if rest.starts_with('{')
2841	                    || rest.starts_with("fn")
2842	                    || rest.starts_with("impl")
2843	                    || rest.starts_with("trait")
2844	                {
2845	                    return true;
2846	                }
2847	            }
2848	            i = after;
2849	            if i > line.len() {
2850	                break;
2851	            }
2852	        }
2853	        false
2854	    }
