1	//! Bounded, incremental conversion of caller-supplied JS values.
2	//!
3	//! napi-derive converts a `Vec<Vec<JsToonValue>>` or `String` parameter in full before the export's body runs, so a
4	//! size check in the body comes too late: a rejected 100,001 × 100 `rows` array cost 3.4 s and 2.6 GiB, and 10k × 10
5	//! cells sharing one 100 KB JS string were copied out once per cell (~10 GB). The exports therefore take untyped napi
6	//! values and convert them here: array lengths are checked before any element is read, and every string's UTF-8
7	//! length is read and charged to a per-call [`Budget`] before the string is copied.
8	
9	use napi::bindgen_prelude::{FromNapiValue, JsObjectValue as _, Object, Unknown};
10	use napi::{JsString, JsValue as _, ValueType};
11	
12	use super::num::JsCount;
13	use super::{JsFailedOp, JsKvItem, JsOpRef, JsPipelineStep, JsRecoveryHint, JsStatusItem, JsToonValue};
14	
15	/// Most cells (row values) one call may pass.
16	pub(crate) const MAX_CELLS: usize = 1_000_000;
17	/// Most UTF-8 bytes of string data one call may pass, summed over every string argument and nested string.
18	pub(crate) const MAX_INPUT_BYTES: usize = 64 * 1024 * 1024;
19	/// Longest single cell value, hint, reason, description or message, in UTF-8 bytes.
20	pub(crate) const MAX_STRING_BYTES: usize = 1024 * 1024;
21	/// Longest type name, field name, key, tool name, error code, truncation hint or other identifier, in UTF-8 bytes.
22	pub(crate) const MAX_NAME_BYTES: usize = 4 * 1024;
23	
24	/// `"{what} length {len} exceeds maximum of {max}"` when `len > max`.
25	pub(crate) fn check_len(what: &str, len: usize, max: usize) -> napi::Result<()> {
26	    if len > max {
27	        return Err(napi::Error::from_reason(format!("{what} length {len} exceeds maximum of {max}")));
28	    }
29	    Ok(())
30	}
31	
32	/// A JS array whose length has been read but none of whose elements have.
33	pub(crate) struct List<'env> {
34	    obj: Object<'env>,
35	    len: u32,
36	}
37	
38	impl<'env> List<'env> {
39	    /// `value` as an array, or an error saying `what` must be one.
40	    pub(crate) fn new(value: Unknown<'env>, what: &str) -> napi::Result<Self> {
41	        if !value.is_array()? {
42	            return Err(napi::Error::from_reason(format!("{what} must be an array")));
43	        }
44	        // Coercing an object to an object returns it unchanged.
45	        let obj = value.coerce_to_object()?;
46	        let len = obj.get_array_length_unchecked()?;
47	        Ok(Self { obj, len })
48	    }
49	
50	    /// `value` as an array, or `None` when it is absent, `undefined` or `null`.
51	    pub(crate) fn optional(value: Option<Unknown<'env>>, what: &str) -> napi::Result<Option<Self>> {
52	        match value {
53	            Some(v) if !is_nullish(v)? => Self::new(v, what).map(Some),
54	            _ => Ok(None),
55	        }
56	    }
57	
58	    /// The element count.
59	    pub(crate) fn len(&self) -> usize {
60	        usize::try_from(self.len).unwrap_or(usize::MAX)
61	    }
62	
63	    fn get(&self, index: u32) -> napi::Result<Unknown<'env>> {
64	        self.obj.get_element::<Unknown<'env>>(index)
65	    }
66	}
67	
68	pub(crate) fn is_nullish(value: Unknown<'_>) -> napi::Result<bool> {
69	    Ok(matches!(value.get_type()?, ValueType::Undefined | ValueType::Null))
70	}
71	
72	fn missing(name: &str) -> napi::Error {
73	    napi::Error::from_reason(format!("Missing field `{name}`"))
74	}
75	
76	/// `value` as an object, or an error saying `what` must be one.
77	pub(crate) fn object<'env>(value: Unknown<'env>, what: &str) -> napi::Result<Object<'env>> {
78	    if value.get_type()? != ValueType::Object {
79	        return Err(napi::Error::from_reason(format!("{what} must be an object")));
80	    }
81	    value.coerce_to_object()
82	}
83	
84	/// Property `name`, or `None` when it is absent or `undefined`. As with napi-derive's generated object conversion,
85	/// `null` is a value (and so rejected wherever a string, number or object is expected), not an absent field.
86	fn prop<'env>(obj: &Object<'env>, name: &str) -> napi::Result<Option<Unknown<'env>>> {
87	    obj.get::<Unknown<'env>>(name)
88	}
89	
90	/// A scalar property converted by its type's own `FromNapiValue` (the numeric newtypes reject out-of-domain numbers
91	/// with their usual messages); `None` when absent or `undefined`.
92	pub(crate) fn typed_prop<T: FromNapiValue>(obj: &Object<'_>, name: &str) -> napi::Result<Option<T>> {
93	    obj.get::<T>(name)
94	}
95	
96	/// A required array property.
97	pub(crate) fn list_prop<'env>(obj: &Object<'env>, name: &str) -> napi::Result<List<'env>> {
98	    List::new(prop(obj, name)?.ok_or_else(|| missing(name))?, name)
99	}
100	
101	/// Per-call accounting of cells and string bytes.
102	pub(crate) struct Budget {
103	    cells: usize,
104	    bytes: usize,
105	}
106	
107	impl Budget {
108	    /// A fresh budget for one export call.
109	    pub(crate) fn new() -> Self {
110	        Self { cells: 0, bytes: 0 }
111	    }
112	
113	    /// Charge `n` cells, failing once the call's total passes [`MAX_CELLS`].
114	    fn charge_cells(&mut self, n: usize) -> napi::Result<()> {
115	        self.cells = self.cells.saturating_add(n);
116	        if self.cells > MAX_CELLS {
117	            return Err(napi::Error::from_reason(format!("cell count {} exceeds maximum of {MAX_CELLS}", self.cells)));
118	        }
119	        Ok(())
120	    }
121	
122	    /// Copy the JS string `value` out after checking it is a string of at most `max` UTF-8 bytes and charging its
123	    /// length to the call's byte budget. The UTF-16 length rejects most oversize strings without scanning them,
124	    /// since a string never has fewer UTF-8 bytes than UTF-16 units.
125	    pub(crate) fn string(&mut self, value: Unknown<'_>, what: &str, max: usize) -> napi::Result<String> {
126	        if value.get_type()? != ValueType::String {
127	            return Err(napi::Error::from_reason(format!("{what} must be a string")));
128	        }
129	        let s: JsString<'_> = value.coerce_to_string()?;
130	        let units = s.utf16_len()?;
131	        if units > max {
132	            return Err(napi::Error::from_reason(format!(
133	                "{what} byte length (at least {units}) exceeds maximum of {max}"
134	            )));
135	        }
136	        let len = s.utf8_len()?;
137	        if len > max {
138	            return Err(napi::Error::from_reason(format!("{what} byte length {len} exceeds maximum of {max}")));
139	        }
140	        self.bytes = self.bytes.saturating_add(len);
141	        if self.bytes > MAX_INPUT_BYTES {
142	            return Err(napi::Error::from_reason(format!(
143	                "input byte total {} exceeds maximum of {MAX_INPUT_BYTES}",
144	                self.bytes
145	            )));
146	        }
147	        s.into_utf8()?.into_owned()
148	    }
149	
150	    /// An optional string property: `None` when absent or `undefined`.
151	    pub(crate) fn opt_string_prop(
152	        &mut self,
153	        obj: &Object<'_>,
154	        name: &str,
155	        what: &str,
156	        max: usize,
157	    ) -> napi::Result<Option<String>> {
158	        match prop(obj, name)? {
159	            Some(value) => self.string(value, what, max).map(Some),
160	            None => Ok(None),
161	        }
162	    }
163	
164	    /// An optional string property where `null` also means absent, for fields whose TypeScript type admits `null`.
165	    fn nullable_string_prop(&mut self, obj: &Object<'_>, name: &str, max: usize) -> napi::Result<Option<String>> {
166	        match prop(obj, name)? {
167	            Some(value) if !is_nullish(value)? => self.string(value, name, max).map(Some),
168	            _ => Ok(None),
169	        }
170	    }
171	
172	    /// A required string property.
173	    pub(crate) fn string_prop(&mut self, obj: &Object<'_>, name: &str, what: &str, max: usize) -> napi::Result<String> {
174	        self.opt_string_prop(obj, name, what, max)?.ok_or_else(|| missing(name))
175	    }
176	
177	    /// An array of strings: its length checked against `max_len` first, then each string against `max_item`.
178	    pub(crate) fn strings(
179	        &mut self,
180	        list: &List<'_>,
181	        what_len: &str,
182	        max_len: usize,
183	        what_item: &str,
184	        max_item: usize,
185	    ) -> napi::Result<Vec<String>> {
186	        check_len(what_len, list.len(), max_len)?;
187	        let mut out = Vec::with_capacity(list.len());
188	        for i in 0..list.len {
